diff --git a/src/test/java/hotel/web/HttpApiTest.java b/src/test/java/hotel/web/HttpApiTest.java
index f9a3f6f..acd8d7f 100644
--- a/src/test/java/hotel/web/HttpApiTest.java
+++ b/src/test/java/hotel/web/HttpApiTest.java
@@ -119,4 +119,77 @@ class HttpApiTest {
         assertEquals(400, get("/reports/revenue?month=july").statusCode());
         assertEquals(400, get("/reports/occupancy").statusCode());
     }
+
+    @Test
+    void acceptsCompanyIdentification() throws Exception {
+        String companyReservation = """
+                {"roomNumber": 201, "guestName": "Ana Souza", "guestEmail": "ana@company.com",
+                 "companyCnpj": "12.345.678/0001-90", "companyName": "Tecnosul Ltda",
+                 "checkIn": "2027-03-10", "checkOut": "2027-03-12",
+                 "guests": 1, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> created = post("/reservations", companyReservation);
+        assertEquals(201, created.statusCode());
+        JsonNode reservation = json.readTree(created.body());
+        assertEquals("Ana Souza", reservation.get("guestName").asText());
+        assertEquals("12.345.678/0001-90", reservation.get("companyCnpj").asText());
+        assertEquals("Tecnosul Ltda", reservation.get("companyName").asText());
+        assertTrue(reservation.get("text").asText().contains("Fatura de hospedagem"));
+        assertTrue(reservation.get("text").asText().contains("Tecnosul Ltda"));
+    }
+
+    @Test
+    void acceptsPassportIdentification() throws Exception {
+        String foreignerReservation = """
+                {"roomNumber": 201, "guestName": "John Smith", "guestEmail": "john@example.com",
+                 "guestPassport": "X1234567", "guestCountry": "United Kingdom",
+                 "checkIn": "2027-03-10", "checkOut": "2027-03-12",
+                 "guests": 1, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> created = post("/reservations", foreignerReservation);
+        assertEquals(201, created.statusCode());
+        JsonNode reservation = json.readTree(created.body());
+        assertEquals("John Smith", reservation.get("guestName").asText());
+        assertEquals("X1234567", reservation.get("guestPassport").asText());
+        assertEquals("United Kingdom", reservation.get("guestCountry").asText());
+        assertTrue(reservation.get("text").asText().contains("Booking receipt"));
+        assertTrue(reservation.get("text").asText().contains("United Kingdom"));
+    }
+
+    @Test
+    void rejectsMultipleIdentifications() throws Exception {
+        String multipleIds = """
+                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
+                 "guestCpf": "111.222.333-44", "companyCnpj": "12.345.678/0001-90", "companyName": "Test",
+                 "checkIn": "2027-03-10", "checkOut": "2027-03-12",
+                 "guests": 1, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> response = post("/reservations", multipleIds);
+        assertEquals(400, response.statusCode());
+        assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
+    }
+
+    @Test
+    void rejectsNoIdentification() throws Exception {
