112	    private static int httpStatus(ErrorCode errorCode) {
113	        return switch (errorCode) {
114	            case INVALID_REQUEST -> 400;
115	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
116	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
117	            case CAPACITY_EXCEEDED -> 422;
118	        };
119	    }
120	
121	    private static NewReservation readNewReservation(Context ctx) {
122	        CreateReservationRequest body;
123	        try {
124	            body = ctx.bodyAsClass(CreateReservationRequest.class);
125	        } catch (Exception unreadableBody) {
126	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
127	        }
128	        if (body == null
129	                || body.roomNumber() == null
130	                || isBlank(body.guestName())
131	                || isBlank(body.guestEmail())
132	                || body.checkIn() == null
133	                || body.checkOut() == null
134	                || body.guests() == null
135	                || body.ratePlan() == null) {
136	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
137	        }
138	
139	        int identificationCount = 0;
140	        if (!isBlank(body.guestCpf())) identificationCount++;
141	        if (!isBlank(body.companyCnpj()) || !isBlank(body.companyName())) identificationCount++;
142	        if (!isBlank(body.guestPassport()) || !isBlank(body.guestCountry())) identificationCount++;
143	
144	        if (identificationCount != 1) {
145	            throw new HotelException(ErrorCode.INVALID_REQUEST,
146	                    "provide either guestCpf, or companyCnpj with companyName, or guestPassport with guestCountry");
147	        }
148	
149	        Guest guest;
150	        if (!isBlank(body.guestCpf())) {
151	            guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
152	        } else if (!isBlank(body.companyCnpj()) && !isBlank(body.companyName())) {
153	            guest = new Guest(body.guestName(), body.guestEmail(), null, body.companyCnpj(), body.companyName(), null, null);
154	        } else {
155	            guest = new Guest(body.guestName(), body.guestEmail(), null, null, null, body.guestPassport(), body.guestCountry());
156	        }
157	
158	        return new NewReservation(
159	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
160	    }
161	
162	    private static long reservationId(Context ctx) {
163	        String id = ctx.pathParam("id");
164	        try {
165	            return Long.parseLong(id);
166	        } catch (NumberFormatException notANumber) {
167	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
168	        }
169	    }
170	
171	    private static LocalDate readDate(Context ctx) {
172	        String date = requiredQueryParam(ctx, "date");
173	        try {
174	            return LocalDate.parse(date);
175	        } catch (DateTimeParseException badDate) {
176	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
177	        }
178	    }
179	
180	    private static YearMonth readMonth(Context ctx) {
181	        String month = requiredQueryParam(ctx, "month");
182	        try {
183	            return YearMonth.parse(month);
184	        } catch (DateTimeParseException badMonth) {
185	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
186	        }
187	    }
188	
189	    private static String requiredQueryParam(Context ctx, String name) {
190	        String value = ctx.queryParam(name);
191	        if (value == null) {
192	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
193	        }
194	        return value;
195	    }
196	
197	    private static boolean isBlank(String text) {
198	        return text == null || text.isBlank();
199	    }
