177	        }
178	    }
179	
180	    private static YearMonth readMonth(Context ctx) {
181	        String month = requiredQueryParam(ctx, "month");
182	        try {
183	            return YearMonth.parse(month);
184	        } catch (DateTimeParseException badMonth) {
185	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
186	        }
187	    }
188	
189	    private static String requiredQueryParam(Context ctx, String name) {
190	        String value = ctx.queryParam(name);
191	        if (value == null) {
192	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
193	        }
194	        return value;
195	    }
196	
197	    private static boolean isBlank(String text) {
198	        return text == null || text.isBlank();
199	    }
